:root {
--radius-none: 0;
--radius-sm: 4px;      /* 체크박스·태그 */
--radius-md: 8px;      /* 버튼 M·입력창·드롭다운 */
--radius-lg: 12px;     /* 카드·말풍선·모달 */
--radius-xl: 20px;     /* 위젯 패널·큰 입력 */
--radius-smooth: 42%;  /* 아바타·런처·앱 아이콘 (스무스 코너 근사) */
--radius-full: 9999px;
--shadow-none: none;
--shadow-sm: inset 0 0 2px rgba(255,255,255,0.08), 0 0 2px 1px rgba(0,0,0,0.08), 0 1px 2px rgba(0,0,0,0.15);   /* ev1 — 말풍선·리스트 카드 */
--shadow-md: inset 0 0 2px rgba(255,255,255,0.08), 0 0 2px 1px rgba(0,0,0,0.08), 0 2px 6px rgba(0,0,0,0.15);   /* ev2 — 카드 hover·툴팁 */
--shadow-lg: inset 0 0 2px rgba(255,255,255,0.08), 0 0 2px 1px rgba(0,0,0,0.08), 0 4px 16px rgba(0,0,0,0.20);  /* ev3 — 드롭다운·팝오버 */
--shadow-xl: inset 0 0 2px rgba(255,255,255,0.08), 0 0 2px 1px rgba(0,0,0,0.08), 0 6px 40px rgba(0,0,0,0.60);  /* ev5 — 모달·채팅 위젯 패널 */
--duration-fast: 150ms;   /* transition.s — 호버·토글 */
--duration-base: 300ms;   /* transition.m — 패널·드롭다운 */
--duration-slow: 450ms;   /* transition.l — 위젯 열림·모달 */
--ease-out: cubic-bezier(0.3, 0, 0, 1);      /* timing-function.default */
--ease-in-out: cubic-bezier(0.3, 0, 0, 1);   /* 별도 in-out 없음 — 같은 곡선 재사용 */
}
:root {
  /* Primary - Bezier Blue (다크 기본) */
  --color-primary-50:  #2A2C45;  /* (추정) blue.300 15% 를 grey.900 에 합성 — 선택 행 배경 */
  --color-primary-100: #313662;  /* (추정) blue.300 30% 합성 — 칩 호버 */
  --color-primary-200: #3E4585;  /* (추정) blue.300 45% 합성 — 포커스 링 면 */
  --color-primary-300: #4E40C9;  /* blue.500 */
  --color-primary-400: #5E56F0;  /* blue.400 — bgtxt-blue-dark (다크) */
  --color-primary-500: #6687FF;  /* blue.300 — bgtxt-blue-normal (다크) 기본 버튼·내 말풍선 */
  --color-primary-600: #7F9BFF;  /* (추정) hover — 다크에선 밝아지는 방향 */
  --color-primary-700: #A3B7FF;  /* (추정) 보간 */
  --color-primary-800: #C7D3FF;  /* (추정) 보간 */
  --color-primary-900: #E6EBFF;  /* (추정) 보간 */

  /* Secondary - 브랜드 마크 바이올렛(로고) + Cobalt(accent 시맨틱) */
  --color-secondary-500: #572DFF;  /* 로고 스퀴클 — 테마 무관 고정 */
  --color-accent-500:    #47C8FF;  /* cobalt.300 — accent (다크) */

  /* Neutral - Bezier grey 반전 (0 = 가장 어두움) */
  --color-neutral-0:    #1A1A1C;  /* grey.950 — surface-normal */
  --color-neutral-50:   #242428;  /* grey.900 — bg-white-normal, 데스크 본문 */
  --color-neutral-100:  #2A2B2D;  /* grey.850 — surface-lowest */
  --color-neutral-200:  #313234;  /* grey.800 — bg-white-higher */
  --color-neutral-300:  #464748;  /* grey.700 — bg-white-highest */
  --color-neutral-500:  #7B7B7B;  /* grey.600 */
  --color-neutral-700:  #A7A7AA;  /* grey.500 */
  --color-neutral-900:  #F7F7F8;  /* grey.100 */
  --color-neutral-1000: #FFFFFF;

  /* Semantic - 다크는 300 계열 + 15% 면 */
  --color-success-bg: #273E30;  /* green.300 15% on grey.900 */
  --color-success-fg: #3ACF5A;  /* green.300 */
  --color-warning-bg: #453830;  /* orange.300 15% */
  --color-warning-fg: #FFAB5C;  /* orange.300 */
  --color-error-bg:   #452C30;  /* red.300 15% */
  --color-error-fg:   #FF5C5C;  /* red.300 */
  --color-info-bg:    #293D48;  /* cobalt.300 15% */
  --color-info-fg:    #47C8FF;  /* cobalt.300 */

  /* Surface (배경 위계) */
  --bg-base:     #242428;             /* bg-white-normal (grey.900) — 데스크 본문 */
  --bg-subtle:   #2A2B2D;             /* surface-lowest (grey.850) — 사이드바·위젯 대화 영역 */
  --bg-elevated: #313234;             /* bg-white-higher (grey.800) — 카드·말풍선 */
  --bg-overlay:  rgba(0, 0, 0, 0.60); /* 다크 딤 */

  /* Text 위계 (fg-white 알파를 grey.900 에 합성) */
  --text-primary:    #D3D3D4;  /* txt-black-darkest (white 80%) — 본문 */
  --text-secondary:  #A7A7A9;  /* txt-black-darker (white 60%) */
  --text-tertiary:   #7C7C7E;  /* txt-black-dark (white 40%) */
  --text-on-primary: #FFFFFF;
  --text-disabled:   #505053;  /* txt-black-light (white 20%) */

  /* Border */
  --border-default: #3A3B3E;  /* bg-black-light (white 12%) 합성 */
  --border-subtle:  #313235;  /* bg-black-lighter (white 8%) 합성 */
  --border-strong:  #505053;  /* bg-black-dark (white 20%) 합성 */
  --border-focus:   #6687FF;  /* bgtxt-blue-normal (다크) */
}

[data-theme="light"] {
  /* Primary - Bezier Blue (라이트 기본) */
  --color-primary-50:  #EFEEFE;  /* bg-blue-lightest (400 10%) — 선택 행 배경 */
  --color-primary-100: #DFDDFC;  /* bg-blue-lighter (400 20%) — 칩 호버 */
  --color-primary-200: #CFCCFA;  /* bg-blue-light (400 30%) — 포커스 링 면 */
  --color-primary-300: #A6A1F7;  /* (추정) 보간 */
  --color-primary-400: #7E77F3;  /* (추정) 보간 — 다크 대비 링크 */
  --color-primary-500: #5E56F0;  /* bgtxt-blue-normal — 기본 버튼·내 말풍선 */
  --color-primary-600: #4E40C9;  /* bgtxt-blue-dark — hover/pressed */
  --color-primary-700: #3F34A3;  /* (추정) 보간 */
  --color-primary-800: #2F277A;  /* (추정) 보간 */
  --color-primary-900: #201A52;  /* (추정) 보간 */

  /* Secondary - 브랜드 마크 바이올렛(로고) + Cobalt(accent 시맨틱) */
  --color-secondary-500: #572DFF;  /* 로고 스퀴클 실측 (channel.io) */
  --color-accent-500:    #329BE7;  /* bgtxt-cobalt-normal — accent 시맨틱 */

  /* Neutral - Bezier grey */
  --color-neutral-0:    #FFFFFF;  /* surface-normal */
  --color-neutral-50:   #FCFCFC;  /* grey.50 — surface-lower */
  --color-neutral-100:  #F7F7F8;  /* grey.100 — surface-lowest, 위젯 채팅 배경 */
  --color-neutral-200:  #EFEFF0;  /* grey.200 — 입력 비활성 면 */
  --color-neutral-300:  #E2E2E4;  /* grey.300 */
  --color-neutral-500:  #A7A7AA;  /* grey.500 — 아이콘 비활성 */
  --color-neutral-700:  #464748;  /* grey.700 */
  --color-neutral-900:  #242428;  /* grey.900 — 제목·로고타입 */
  --color-neutral-1000: #000000;

  /* Semantic - success=green, warning=orange, critical=red, accent=cobalt */
  --color-success-bg: #EAF6EE;  /* green.400 10% */
  --color-success-fg: #31A552;  /* green.400 */
  --color-warning-bg: #FEF2E7;  /* orange.400 10% */
  --color-warning-fg: #F4800B;  /* orange.400 */
  --color-error-bg:   #FDEDEE;  /* red.400 10% */
  --color-error-fg:   #E94E58;  /* red.400 */
  --color-info-bg:    #EBF5FD;  /* cobalt.400 10% */
  --color-info-fg:    #329BE7;  /* cobalt.400 */

  /* Surface (배경 위계) */
  --bg-base:     #FFFFFF;             /* bg-white-normal — 데스크 본문 */
  --bg-subtle:   #F7F7F8;             /* surface-lowest — 사이드바·위젯 대화 영역 */
  --bg-elevated: #FFFFFF;             /* bg-white-high — 카드·말풍선 */
  --bg-overlay:  rgba(0, 0, 0, 0.40); /* dim-black-normal — 모달 딤 */

  /* Text 위계 (fg-black 알파를 흰 바탕에 합성) */
  --text-primary:    #262626;  /* txt-black-darkest (black 85%) — 본문 */
  --text-secondary:  #666666;  /* txt-black-darker (black 60%) — 보조 */
  --text-tertiary:   #999999;  /* txt-black-dark (black 40%) — 시간·캡션 */
  --text-on-primary: #FFFFFF;  /* bgtxt-absolute-white */
  --text-disabled:   #D9D9D9;  /* txt-black-light (black 15%) */

  /* Border */
  --border-default: #EBEBEB;  /* bg-black-light (black 8%) */
  --border-subtle:  #F2F2F2;  /* bg-black-lighter (black 5%) */
  --border-strong:  #D9D9D9;  /* bg-black-dark (black 15%) */
  --border-focus:   #5E56F0;  /* bgtxt-blue-normal */
}




.ct-btn { height: 36px; padding: 0 14px; border: 0; border-radius: var(--radius-md); font: 700 14px/18px Inter, 'Noto Sans KR', sans-serif; letter-spacing: -0.1px; display: inline-flex; align-items: center; gap: 6px; cursor: pointer; transition: background var(--duration-fast) var(--ease-out); }
.ct-btn--primary { background: var(--color-primary-500); color: var(--text-on-primary); }
.ct-btn--primary:hover { background: var(--color-primary-600); }
.ct-btn--primary:active { background: var(--color-primary-700); }
.ct-btn--secondary { background: var(--color-primary-50); color: var(--color-primary-500); }
.ct-btn--secondary:hover { background: var(--color-primary-100); }
.ct-btn--ghost { background: transparent; color: var(--text-secondary); }
.ct-btn--ghost:hover { background: var(--border-subtle); color: var(--text-primary); }
.ct-btn--danger { background: var(--color-error-fg); color: var(--text-on-primary); }
.ct-btn--danger:hover { filter: brightness(0.92); }
.ct-btn:disabled { opacity: 0.4; cursor: not-allowed; }           /* Bezier opacity disabled 0.4 */
.ct-btn.is-loading { color: transparent; position: relative; pointer-events: none; }
.ct-btn.is-loading::after { content: ""; position: absolute; left: 50%; top: 50%; width: 16px; height: 16px; margin: -8px 0 0 -8px; border: 2px solid rgba(255,255,255,0.4); border-top-color: #fff; border-radius: 50%; animation: ct-spin 0.8s linear infinite; }
@keyframes ct-spin { to { transform: rotate(360deg); } }
.ct-input { height: 36px; padding: 0 12px; border: 0; border-radius: var(--radius-md); background: var(--bg-elevated); color: var(--text-primary); box-shadow: inset 0 0 0 1px var(--border-default); font: 400 14px/18px Inter, 'Noto Sans KR', sans-serif; }
.ct-input:focus { outline: none; box-shadow: inset 0 0 0 1px var(--border-focus), 0 0 0 3px var(--color-primary-100); }
.ct-input.is-error { box-shadow: inset 0 0 0 1px var(--color-error-fg), 0 0 0 3px var(--color-error-bg); }
.ct-input:disabled { background: var(--bg-subtle); color: var(--text-disabled); }
.ct-card { background: var(--bg-elevated); border-radius: var(--radius-lg); padding: 16px; box-shadow: var(--shadow-sm); }
.ct-card:hover { box-shadow: var(--shadow-md); }
.ct-card--accent { background: var(--color-primary-50); box-shadow: none; }
.ct-card--outlined { box-shadow: inset 0 0 0 1px var(--border-default); }
.ct-badge { display: inline-flex; align-items: center; height: 20px; padding: 0 6px; border-radius: var(--radius-sm); font: 700 11px/16px Inter, sans-serif; }
.ct-badge--solid { background: var(--color-primary-500); color: #fff; }
.ct-badge--subtle { background: var(--color-primary-50); color: var(--color-primary-500); }
.ct-badge--outline { box-shadow: inset 0 0 0 1px var(--border-strong); color: var(--text-secondary); }
.ct-unread { min-width: 18px; height: 18px; padding: 0 5px; border-radius: 9px; background: var(--color-error-fg); color: #fff; font: 700 11px/18px Inter, sans-serif; text-align: center; }  /* 안 읽은 상담 수 */
.ct-rail { width: 64px; background: var(--bg-subtle); display: flex; flex-direction: column; align-items: center; gap: 4px; padding: 12px 0; box-shadow: 1px 0 0 var(--border-default); }
.ct-rail__item { width: 40px; height: 40px; border-radius: var(--radius-md); display: grid; place-items: center; color: var(--text-tertiary); }
.ct-rail__item:hover { background: var(--border-subtle); color: var(--text-secondary); }
.ct-rail__item.is-active { background: var(--color-primary-50); color: var(--color-primary-500); }
.ct-avatar { width: 32px; height: 32px; border-radius: var(--radius-smooth); object-fit: cover; }
